using Microsoft.VisualStudio.TestTools.UnitTesting;
using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup()
    {
        _tracker = new InventoryTracker();
    }

    // --- Stock Level Tests ---

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        int level = _tracker.GetStockLevel("UNKNOWN-001");

        Assert.AreEqual(0, level);
    }

    [TestMethod]
    public void AddStock_NewSku_SetsStockLevel()
    {
        _tracker.AddStock("SKU-100", 50);

        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-100"));
    }

    [TestMethod]
    public void AddStock_ExistingSku_AccumulatesQuantity()
    {
        _tracker.AddStock("SKU-200", 30);
        _tracker.AddStock("SKU-200", 20);

        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-200"));
    }

    [TestMethod]
    public void AddStock_MultipleSkus_TracksIndependently()
    {
        _tracker.AddStock("SKU-A", 10);
        _tracker.AddStock("SKU-B", 25);

        Assert.AreEqual(10, _tracker.GetStockLevel("SKU-A"));
        Assert.AreEqual(25, _tracker.GetStockLevel("SKU-B"));
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddStock_NegativeQuantity_ThrowsArgumentException()
    {
        _tracker.AddStock("SKU-100", -5);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public void AddStock_NullSku_ThrowsArgumentNullException()
    {
        _tracker.AddStock(null!, 10);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddStock_ZeroQuantity_ThrowsArgumentException()
    {
        _tracker.AddStock("SKU-100", 0);
    }

    // --- Reorder Alert Tests ---

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-300", 100);

        Assert.IsFalse(_tracker.NeedsReorder("SKU-300"));
    }

    [TestMethod]
    public void NeedsReorder_StockAtZero_ReturnsTrue()
    {
        Assert.IsTrue(_tracker.NeedsReorder("SKU-EMPTY"));
    }

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-LOW", 1);

        Assert.IsTrue(_tracker.NeedsReorder("SKU-LOW"));
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public void NeedsReorder_NullSku_ThrowsArgumentNullException()
    {
        _tracker.NeedsReorder(null!);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public void GetStockLevel_NullSku_ThrowsArgumentNullException()
    {
        _tracker.GetStockLevel(null!);
    }
}

